"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["2698"],{13910(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.cascata_origem_ausente","status":422,"titulo":"Uma modalidade SegueCascata n\xe3o tem sequ\xeancia de destinos declarada na cascata do processo"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.cascata_origem_ausente","requisitos":["UNI-REQ-0056"],"oQueAconteceu":["Uma modalidade com `regraRemanejamento` igual a `SEGUE_ORDEM_DE_REMANEJAMENTO` n\xe3o tem\\nnenhuma sequ\xeancia de destinos declarada para ela na cascata do processo\\n(cascata de remanejamento de cotas, UNI-REQ-0056). Essa causa cobre dois cen\xe1rios distintos:","- O processo **n\xe3o tem cascata de remanejamento configurada** \u2014\\n  nenhuma modalidade pode seguir uma cascata que n\xe3o existe.\\n- O processo **tem** cascata, mas ela n\xe3o declara o c\xf3digo dessa\\n  modalidade espec\xedfica como origem \u2014 ela cobre outras origens, mas n\xe3o\\n  esta.","O primeiro cen\xe1rio \xe9 conferido uma vez por oferta, antes de examinar cada\\nmodalidade individualmente \u2014 a partir da\xed, se o processo tiver cascata, o\\nsegundo cen\xe1rio \xe9 conferido para cada modalidade `SEGUE_ORDEM_DE_REMANEJAMENTO` da\\noferta, em ordem determin\xedstica (por c\xf3digo). Sequencial: a primeira\\noferta ou modalidade com essa inconsist\xeancia interrompe a avalia\xe7\xe3o de\\nconformidade estrutural para publica\xe7\xe3o; nunca acumula com nenhuma outra\\ncausa desta s\xe9rie."],"comoResolver":["Configure a cascata de remanejamento do processo, se ainda n\xe3o existir, ou\\nadicione a modalidade apontada como origem na cascata j\xe1 configurada \u2014\\ncom ao menos um destino em sua fila. Se a modalidade n\xe3o deveria seguir a\\ncascata, corrija o `remanejamento.regra` dela."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);